// 1. 第一次选完，只把 ID 存起来
const first = await openPersonPicker({ mode: 'multiple' });
if (first.ok && !first.closed) {
  await saveToServer({
    userIds: first.result.filter(e => e.type === 'person').map(e => e.id),
    orgIds:  first.result.filter(e => e.type === 'org').map(e => e.id),
  });
}

